Q: Error while removing duplicates from a std::vector containing std::variant A: <p>I would add custom comparator and thenge the output generation</p>
<pre><code>#include &lt;iostream&gt;
#include &lt;vector&gt;
#include &lt;algorithm&gt;
#include &lt;variant&gt;

template &lt;typename T&gt; 
void valueRemoveTemplate(std::vector&lt;T&gt;&amp; vec) {
    // Explicitly using variant's &lt; 
    std::sort(vec.begin(), vec.end(), [](const T&amp; a, const T&amp; b) {
        return a &lt; b; 
    });

    // Explicitly using variant's ==
    auto last = std::unique(vec.begin(), vec.end(), [](const T&amp; a, const T&amp; b) {
        return a == b;
    });

    vec.erase(last, vec.end());

    std::cout &lt;&lt; &quot;No duplicates: &quot;;
    for (const auto&amp; i : vec) {
        std::visit([](auto&amp;&amp; arg) { std::cout &lt;&lt; arg &lt;&lt; &quot; &quot;; }, i);
    }
    std::cout &lt;&lt; std::endl;
}

int main() {
    // Works with char, int, double variant
    std::vector&lt;std::variant&lt;char, int, double&gt;&gt; any_vector = {0, 'a', 0, 3.5, 'a', 'a'};
    valueRemoveTemplate(any_vector);
    return 0;
}
</code></pre>

